policies = {
    "app-role": [{"Effect": "Allow", "Action": ["s3:GetObject"], "Resource": "arn:aws:s3:::pay-receipts/*"}],
    "legacy-admin": [{"Effect": "Allow", "Action": ["*"], "Resource": "*"}],
    "batch-role": [{"Effect": "Allow", "Action": ["kms:*"], "Resource": "*"}],
}
security_groups = [
    {"id": "sg-web", "port": 443, "cidr": "0.0.0.0/0"},
    {"id": "sg-bastion", "port": 22, "cidr": "0.0.0.0/0"},
    {"id": "sg-db", "port": 3306, "cidr": "10.0.0.0/16"},
]
for name, stmts in policies.items():
    for s in stmts:
        wide = any(a == "*" or a.endswith(":*") for a in s["Action"])
        if s["Effect"] == "Allow" and (wide or s["Resource"] == "*"):
            print("IAM", name, s["Action"], s["Resource"], "-> 권한 과다")
ADMIN_PORTS = {22, 3389, 3306}
for g in security_groups:
    if g["cidr"] == "0.0.0.0/0" and g["port"] in ADMIN_PORTS:
        print("SG", g["id"], g["port"], "-> 관리 포트가 인터넷 전체에 열림")
# IAM legacy-admin ['*'] * -> 권한 과다
# IAM batch-role ['kms:*'] * -> 권한 과다
# SG sg-bastion 22 -> 관리 포트가 인터넷 전체에 열림

findings = [
    {"id": "W-01", "target": "결제 홈페이지", "result": "취약", "fixed": True},
    {"id": "W-07", "target": "결제 홈페이지", "result": "취약", "fixed": False, "alt": "WAF 규칙으로 차단"},
    {"id": "U-13", "target": "정산 서버", "result": "취약", "fixed": False},
    {"id": "U-02", "target": "정산 서버", "result": "양호", "fixed": None},
]
for f in findings:
    if f["result"] != "취약":
        continue
    if f["fixed"]:
        state = "제거 완료"
    elif f.get("alt"):
        state = "상응 조치: " + f["alt"]
    else:
        state = "제거·상응 조치 불가 -> 최고경영자 승인 필요"
    print(f["id"], f["target"], "->", state)
# W-01 결제 홈페이지 -> 제거 완료
# W-07 결제 홈페이지 -> 상응 조치: WAF 규칙으로 차단
# U-13 정산 서버 -> 제거·상응 조치 불가 -> 최고경영자 승인 필요

import csv, io
hr = io.StringIO("emp_id,name,status\nE01,김가,재직\nE02,이나,퇴사\nE03,박다,재직\n")
accounts = io.StringIO("account,emp_id,last_login_days\nkim.ga,E01,1\nlee.na,E02,40\npark.da,E03,120\nsvc-batch,,2\n")
status = {r["emp_id"]: r["status"] for r in csv.DictReader(hr)}
for a in csv.DictReader(accounts):
    if not a["emp_id"]:
        print(a["account"], "-> 주인 없는 계정(서비스 계정이면 담당자 지정)")
    elif status.get(a["emp_id"]) == "퇴사":
        print(a["account"], "-> 퇴사자 계정, 즉시 잠금")
    elif int(a["last_login_days"]) > 90:
        print(a["account"], "-> 90일 미사용, 잠금 검토")
# lee.na -> 퇴사자 계정, 즉시 잠금
# park.da -> 90일 미사용, 잠금 검토
# svc-batch -> 주인 없는 계정(서비스 계정이면 담당자 지정)
